def hook(ctx, nb):
    return {
        "skills": [
            {
                "text": "Always enclose table and column names that contain spaces or special characters in backticks (e.g., `My Table`)."
            }
        ],
        "tool_hint": "Use backticks for identifiers with spaces."
    }

def description_keywords():
    return [
        "successfully", "completed", "inserted", "updated", "modified",
        "record has been", "the table", "data has been", "row has been",
        "set to", "changed to", "added to", "deleted from",
        "no such", "does not exist", "does not exists",
        "the answer is", "the result is", "query returned",
        "select ", "update ", "insert ", "delete ",
        "the ", " is ", " was ", " has ", " are ", " will ",
        "field ", "column ", "value ", "record "
    ]

def is_description(text):
    if not text or not isinstance(text, str):
        return False
    lower = text.lower()
    if len(text) > 120 and " " in text:
        return True
    for kw in description_keywords():
        if kw in lower:
            return True
    return False

def has_description_answers(answers):
    for ans in answers:
        if is_description(ans):
            return True
    return False

def hook(ctx, nb):
    if ctx["action"]["tool"] == "commit_final_answer":
        answers = ctx["action"]["answers"]
        if has_description_answers(answers):
            return {
                "kind": "block_and_prompt",
                "message": "Your answer looks like a natural-language description instead of the actual data values. Provide the raw data values as a list of strings (e.g., [\"value1\", \"value2\", ...]) or an empty list if no data matches. Do not include explanatory text."
            }
    return None
